# Fixed income, derivatives, credit and macro scenario drills.
market_cases=[
('Duration move','A bond has modified duration 6.0. Yields rise 50 bps. Ignoring convexity, approximate percentage price change?','About -3%.','ΔP/P≈-6×0.005=-3%.','Duration translates small yield changes into first-order bond price changes.','FI'),
('Convexity intuition','Two bonds have the same duration, but Bond A has higher positive convexity. For a large symmetric yield move, which generally performs better?','Bond A, all else equal.','Positive convexity makes gains for falling yields larger and losses for rising yields smaller versus the linear duration approximation.','Convexity improves curvature of price response, but may be costly.','FI'),
('Clean dirty','Clean price is 101.20 and accrued interest is 1.35. Dirty price?','102.55.','Dirty=Clean+AI=102.55.','Settlement cash includes accrued coupon compensation.','FI'),
('Credit spread','A corporate bond yields 6.4% and comparable government benchmark yields 4.1%. Simple spread?','230 bps.','6.4%-4.1%=2.3%=230 bps.','Spread compensates for credit/liquidity/technical risks beyond benchmark rates.','Credit'),
('Expected loss','PD 3%, LGD 60%, EAD $20m. One-period expected loss?','$360k.','EL=3%×60%×20m=0.36m.','Expected loss combines default frequency, severity and exposure.','Credit'),
('Recovery','A defaulted senior claim of $100 recovers $42. Recovery rate and LGD?','42% recovery, 58% LGD.','Recovery=42/100=42%; LGD=1-42%=58%.','Recovery depends on collateral, seniority and enterprise value.','Credit'),
('Forward no-arb','Spot asset price 100, one-year risk-free rate 5%, no income or storage costs. Simple one-year forward price under annual compounding?','105.','F=100×1.05=105.','Forward price reflects carry under no arbitrage.','Derivatives'),
('Option moneyness','Stock 48, call strike 50. Is the call ITM, ATM or OTM?','OTM by $2.','A call is ITM when S>K; here 48<50.','Moneyness is based on immediate exercise value, not option premium.','Derivatives'),
('Swap direction','A company pays floating debt but wants fixed-rate exposure. What plain-vanilla interest-rate swap direction is the natural hedge?','Pay fixed, receive floating.','The received floating leg offsets the floating-rate exposure on debt, leaving a largely fixed net cost before basis/credit effects.','Hedges should offset the underlying risk factor.','Derivatives'),
('CDS widening','A company’s CDS spread widens sharply with no benchmark-rate move. What does that generally signal?','Higher market-implied credit risk / required credit compensation.','Wider CDS means protection is more expensive, commonly reflecting higher perceived default/loss risk, liquidity or risk premium.','Credit spreads are market prices, not pure default probabilities.','Credit'),
('Inflation surprise','Headline and core CPI print materially above consensus with strong wages. What is a balanced first-pass cross-asset reaction?','Markets may price a tighter policy path: front-end yields up, bonds down, growth equities pressured and USD supported, but reaction depends on prior pricing, positioning and the cause of inflation.','Start with policy expectations, then transmit to discount rates, growth expectations, FX and credit. Do not state any asset move as guaranteed.','Expectations and shock composition determine the actual market response.','Macro'),
('Weak payrolls','Payroll growth is far below consensus while unemployment rises and wage growth cools. What does that tend to do to policy expectations?','It can increase expectations of easier policy / lower future rates, all else equal.','A weaker labour market can reduce inflation pressure and raise recession risk, but revisions, participation and prior pricing matter.','Macro data matter through the reaction function and expectations.','Macro'),
('Rate cut FX','The central bank cuts rates, but the currency strengthens. Give two plausible explanations.','The cut was smaller than priced, or it reduced recession/financial-stability risk enough to improve capital inflows; relative foreign policy expectations may also have shifted.','FX reacts to relative expected paths and risk premia, not the sign of one policy action alone.','Relative expectations dominate simplistic rate-change rules.','Macro'),
('Curve inversion','2-year yield is 5.0% and 10-year is 4.2%. What is 2s10s slope defined as 10y minus 2y?','-80 bps, inverted.','4.2%-5.0%=-0.8%=-80 bps.','An inverted curve often reflects tight near-term policy versus lower expected future rates/term premia.','FI'),
('Risk-off not universal','Why might government yields fall during an equity sell-off?','Safe-haven demand and weaker growth/inflation expectations can push bond prices up and yields down, though inflationary shocks can produce different outcomes.','Cross-asset correlations depend on the nature of the shock.','Do not memorize one risk-on/risk-off map as a law.','Markets'),
]
for i,(topic,q,short,deep,why,sub) in enumerate(market_cases,1):
    cat='Global Markets / Macro' if sub in ('Macro','Markets') else 'Fixed Income / Derivatives' if sub in ('FI','Derivatives') else 'LBO / Credit'
    K(f'CASE-MKT-{i:02d}',cat,sub,'Scenario: '+topic,4,4 if i>10 else 5,q,short,short,deep,why,
      'En mercados, responde condicionalmente: qué estaba priced, causa del movimiento, magnitud, positioning, policy reaction y horizonte.',
      mistake='Treating a market relationship as a deterministic law.',trap='Use “all else equal” and distinguish first-pass mechanics from realised market reaction.',followups=['What could make the opposite happen?'],related=['Expectations','Risk premia'],tags=['markets','scenario'])

# Behavioural/deal-prep frameworks — no invented personal facts.
behavioural=[
('Why Investment Banking?','Give a strong framework for “Why Investment Banking?” without inventing personal experiences.','Structure: genuine motivation → evidence from your own experiences → why the day-to-day work fits → why this platform/team → forward-looking contribution.','Avoid generic prestige/learning claims. Anchor the answer in real evidence the candidate supplies and connect it to transaction work, analytical intensity, teamwork and responsibility.'),
('Why M&A?','Framework for “Why M&A?”','Interest in strategic decisions + valuation/analysis + end-to-end deal execution + working closely with senior decision-makers; prove each with real personal evidence.','A strong answer distinguishes M&A from generic finance and avoids pretending every deal is glamorous.'),
('Why Global Markets?','Framework for “Why Global Markets?”','Motivation for live information, probabilistic thinking, rapid feedback and client/risk interaction; support with real examples.','Show why the pace and market feedback loop fit you, not just that markets are “interesting”.'),
('Why Santander?','How should “Why Santander?” be prepared without inventing internal claims?','Use verified public facts about the specific franchise/team, link them to your goals, then add credible personal fit. Do not claim undocumented cultural or interview facts.','The evergreen bank should provide the framework; current facts belong in a separate refreshed prep module.'),
('Walk me through your CV','Framework for a concise CV walkthrough.','Present → key past pivots/experiences → why they build toward this role → current objective. Keep chronology selective and causal.','A CV walkthrough is a narrative, not a line-by-line reading.'),
('Tell me about a deal','Framework for discussing a recent M&A deal.','Buyer/target → transaction value → consideration → strategic rationale → valuation/premium → financing → synergies → regulatory issues → market reaction → risks → your analysis.','Separate factual deal terms from your own interpretation and verify current facts before interview.'),
('Tell me about a market event','Framework for a market-event answer.','Event/data → what was expected → surprise → first-order moves → cross-asset transmission → why → alternative interpretation → what to watch next.','The key is expectation-relative reasoning, not reciting headlines.'),
('Leadership','Framework for a leadership behavioural answer.','Situation and objective → constraint/conflict → specific actions you personally took → measurable outcome → what you learned/changed.','Show influence, judgment and ownership rather than title alone.'),
('Conflict','Framework for a conflict question.','Context → genuine disagreement → how you surfaced interests/data → decision process → outcome → relationship/lesson.','Do not turn the other person into a villain; show productive disagreement.'),
('Failure / pressure','Framework for failure or pressure questions.','Choose a real meaningful example → own your contribution → corrective action → result → concrete system/process change that reduces recurrence.','Avoid fake weaknesses and outcomes with no personal accountability.'),
]
for i,(topic,q,short,deep) in enumerate(behavioural,1):
    K(f'BEH-{i:02d}','Behavioural','Interview frameworks',topic,2,3,q,short,short,deep,
      'Frameworks make answers structured while preserving authenticity; the content must come from the candidate’s real experiences.',
      'Usa la estructura como guía, pero llena la respuesta solo con experiencias reales y verificables propias.',
      mistake='Using generic claims or inventing evidence.',trap='A polished structure cannot substitute for authentic evidence.',followups=['What concrete evidence from your own experience supports this?'],related=['Interview communication'],tags=['behavioural','framework'],qtype='Interview Question')

# -----------------------------------------------------------------------------
# Expand each core concept into five genuinely different cognitive tasks.
# -----------------------------------------------------------------------------
def clean(x):
    return (x or '').strip()

def expand_concept(c):
    t=c['t']; f=c['f']; base=c['id']; formula=clean(c['formula'])
    formula_display='' if formula.lower() in ('no formula','n/a','none') else formula
    common=c['caveat']
    es=c['es']
    rel=c['related']
    answers=[]
    answers.append(dict(
        id=f'{base}-L1', category=c['cat'],subcategory=c['sub'],topic=t,difficulty=1,interviewFrequency=f,
        questionType='Definition',question=f'What is {t}?',
        shortAnswer=c['d'],idealInterviewAnswer=f"{c['d']} {c['why']}",
        deepExplanation=f"{c['d']} {c['why']} Key caveat: {c['caveat']}",intuition=c['why'],spanishExplanation=es,
        formula=formula_display,variables='',workedExample='',commonMistake=common,interviewerTrap=c['trap_q'],
        followUps=[f'How does {t} work mechanically?',f'Why does {t} matter?'],relatedConcepts=rel,tags=[c['cat'],c['sub'],t,'foundation']))
    q2=f'How does {t} work mechanically, and how would you calculate or derive it?'
    mechanics = (f"A useful formula or relationship is: {formula}. " if formula_display else '') + c['d']
    answers.append(dict(
        id=f'{base}-L2',category=c['cat'],subcategory=c['sub'],topic=t,difficulty=2,interviewFrequency=f,
        questionType='Formula Recall' if formula_display else 'Explain Like an Analyst',question=q2,
        shortAnswer=mechanics,idealInterviewAnswer=f"{mechanics} In practice, {c['why']}",
        deepExplanation=f"{mechanics} The economic point is: {c['why']} Caveat: {c['caveat']}",intuition=c['why'],spanishExplanation=es,
        formula=formula_display,variables='',workedExample='',commonMistake=common,interviewerTrap=c['trap_q'],
        followUps=[f'Why does {t} work?',f'What can make {t} misleading?'],relatedConcepts=rel,tags=[c['cat'],c['sub'],t,'mechanics']))
    answers.append(dict(
        id=f'{base}-L3',category=c['cat'],subcategory=c['sub'],topic=t,difficulty=3,interviewFrequency=f,
        questionType='Intuition',question=f'Why does {t} matter, and when is it useful in CIB?',
        shortAnswer=c['why'],idealInterviewAnswer=f"{c['why']} {c['d']}",
        deepExplanation=f"Use {t} when the analytical question matches what it measures. {c['why']} Do not lose the caveat: {c['caveat']}",
        intuition=c['why'],spanishExplanation=es,formula=formula_display,variables='',workedExample='',commonMistake=common,
        interviewerTrap=c['trap_q'],followUps=[f'What are the limitations of {t}?',c['trap_q']],relatedConcepts=rel,tags=[c['cat'],c['sub'],t,'intuition']))
    answers.append(dict(
        id=f'{base}-L4',category=c['cat'],subcategory=c['sub'],topic=t,difficulty=4,interviewFrequency=max(3,f-1),
        questionType='Advanced Technical',question=f'What are the main limitations, caveats or ways {t} can mislead you?',
        shortAnswer=c['caveat'],idealInterviewAnswer=f"The main caveat is that {c['caveat']} I would interpret it alongside {', '.join(rel[:3]) if rel else 'the underlying economics'} rather than in isolation.",
        deepExplanation=f"{c['caveat']} The correct interpretation depends on the business model, accounting, market context and the exact decision being made. {c['why']}",
        intuition='A strong interview answer identifies both what a metric explains and what it leaves out.',spanishExplanation=es,
        formula=formula_display,variables='',workedExample='',commonMistake=common,interviewerTrap=c['trap_q'],
        followUps=[c['trap_q'],f'What would you cross-check before relying on {t}?'],relatedConcepts=rel,tags=[c['cat'],c['sub'],t,'limitations']))
    answers.append(dict(
        id=f'{base}-L5',category=c['cat'],subcategory=c['sub'],topic=t,difficulty=5,interviewFrequency=f,
        questionType='Trick Question',question=c['trap_q'],shortAnswer=c['trap_a'],idealInterviewAnswer=c['trap_a'],
        deepExplanation=f"{c['trap_a']} The underlying intuition is: {c['why']} Relevant caveat: {c['caveat']}",intuition=c['why'],spanishExplanation=es,
        formula=formula_display,variables='',workedExample='',commonMistake=common,interviewerTrap='⚠ INTERVIEW TRAP',
        followUps=[f'How would you test that conclusion quantitatively?',f'What assumption could make the opposite conclusion reasonable?'],relatedConcepts=rel,tags=[c['cat'],c['sub'],t,'interview-trap']))
    return answers

QUESTIONS=[]
for c in CONCEPTS:
    QUESTIONS.extend(expand_concept(c))
QUESTIONS.extend(CASES)

# Formula sheet is generated only from non-empty unique formulas.
formula_map={}
for q in QUESTIONS:
    f=clean(q.get('formula',''))
    if f and f.lower() not in ('no formula','n/a','none'):
        key=(q['topic'],f)
        if key not in formula_map:
            formula_map[key]=dict(topic=q['topic'],category=q['category'],formula=f,
                interpretation=q.get('intuition',''),whenUsed=q.get('idealInterviewAnswer',''),commonMistake=q.get('commonMistake',''))
FORMULAS=list(formula_map.values())

if __name__=='__main__':
    import json, pathlib, re
    out=pathlib.Path(__file__).parent/'data'
    out.mkdir(exist_ok=True)
    (out/'core.js').write_text('window.CORE_CONCEPTS = '+json.dumps(CONCEPTS,ensure_ascii=False,separators=(',',':'))+';\n',encoding='utf-8')
    (out/'cases.js').write_text('window.CASE_QUESTIONS = '+json.dumps(CASES,ensure_ascii=False,separators=(',',':'))+';\n',encoding='utf-8')
    audit={
      'concepts':len(CONCEPTS),'cases':len(CASES),'questions':len(QUESTIONS),'formulas':len(FORMULAS),
      'by_category':{},'by_difficulty':{},'by_frequency':{}
    }
    for q in QUESTIONS:
        audit['by_category'][q['category']]=audit['by_category'].get(q['category'],0)+1
        audit['by_difficulty'][str(q['difficulty'])]=audit['by_difficulty'].get(str(q['difficulty']),0)+1
        audit['by_frequency'][str(q['interviewFrequency'])]=audit['by_frequency'].get(str(q['interviewFrequency']),0)+1
    (out/'audit.json').write_text(json.dumps(audit,indent=2,ensure_ascii=False),encoding='utf-8')
    print(json.dumps(audit,indent=2,ensure_ascii=False))
